import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { FaFilter, FaPlus } from 'react-icons/fa';
import { useAuth } from '../../context/AuthContext';
import { useLanguage } from '../../context/LanguageContext';
import { useTheme } from '../../context/ThemeContext';
import { useFilters } from '../../hooks/useFilters';
import Button from '../../components/common/Button/Button';
import AdvertCard from '../../components/AdvertCard/AdvertCard';
import FilterSection from '../../components/FilterSection/FilterSection';
import advertService from '../../services/advertService';
import userService from '../../services/userService';
import notificationService from '../../services/notificationService';
import styles from './HomePage.module.css';

const HomePage = () => {
    const navigate = useNavigate();
    const { user, isAuthenticated } = useAuth();
    const { t } = useLanguage();
    const { theme } = useTheme();
    const { filters, showFilters, setShowFilters, applyFilters } = useFilters();

    const [activeTab, setActiveTab] = useState('all');
    const [adverts, setAdverts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [selectedCreator, setSelectedCreator] = useState(null);
    const [showCreatorModal, setShowCreatorModal] = useState(false);
    const [notificationText, setNotificationText] = useState('');

    const isAdminUser = user?.role === 'admin' || user?.isAdmin === true || user?.roleId === 2;

    const levelMap = {
        1: 'D1', 2: 'D2', 3: 'D3', 4: 'D4', 5: 'D4+',
        'D4Plus': 'D4+'
    };

    const loadAdverts = useCallback(async () => {
        setLoading(true);
        setError(null);
        try {
            let response;
            switch (activeTab) {
                case 'my':
                    if (!isAuthenticated) { setAdverts([]); setLoading(false); return; }
                    response = await advertService.getMyAdverts();
                    break;
                case 'participating':
                    if (!isAuthenticated) { setAdverts([]); setLoading(false); return; }
                    response = await advertService.getParticipatingAdverts();
                    break;
                default:
                    response = await advertService.getAllAdverts(filters);
            }
            const advertsData = response.adverts || [];

            if (activeTab === 'participating' && user) {
                const myAdvertsResponse = await advertService.getMyAdverts();
                const myAdverts = myAdvertsResponse.adverts || [];
                const myParticipatingAdverts = myAdverts.filter(advert => advert.isParticipating === true);
                const allParticipating = [...advertsData, ...myParticipatingAdverts];
                const uniqueParticipating = allParticipating.filter((advert, index, self) =>
                    index === self.findIndex(a => a.id === advert.id)
                );
                setAdverts(uniqueParticipating);
            } else {
                setAdverts(advertsData);
            }
        } catch (err) {
            setError(err.message || t('loadingError'));
        } finally {
            setLoading(false);
        }
    }, [activeTab, filters, isAuthenticated, t, user]);

    useEffect(() => { loadAdverts(); }, [loadAdverts]);

    const handleViewCreator = async (creatorId) => {
        try {
            const response = await userService.getUserById(creatorId);
            setSelectedCreator(response.user);
            setShowCreatorModal(true);
        } catch (error) {
            alert('Не удалось загрузить информацию о создателе');
        }
    };

    const handleBlockUser = async () => {
        if (!selectedCreator) return;
        if (window.confirm(`Вы уверены, что хотите ${selectedCreator.isBlocked ? 'разблокировать' : 'заблокировать'} пользователя ${selectedCreator.name}?`)) {
            try {
                if (selectedCreator.isBlocked) {
                    await userService.unblockUser(selectedCreator.id);
                } else {
                    await userService.blockUser(selectedCreator.id);
                }
                const updatedResponse = await userService.getUserById(selectedCreator.id);
                setSelectedCreator(updatedResponse.user);
                alert(`Пользователь ${selectedCreator.isBlocked ? 'разблокирован' : 'заблокирован'}`);
            } catch (err) {
                alert(err.message);
            }
        }
    };

    const handleSendNotification = async () => {
        if (!selectedCreator || !notificationText.trim()) return;
        try {
            await notificationService.sendToUser(selectedCreator.id, notificationText);
            setNotificationText('');
            setShowCreatorModal(false);
            alert('Уведомление отправлено');
        } catch (err) {
            alert(err.message);
        }
    };

    const handleSubscribe = async (advertId) => {
        if (!isAuthenticated) { navigate('/login'); return; }
        try {
            await advertService.subscribeToAdvert(advertId);
            setAdverts(prevAdverts =>
                prevAdverts.map(advert => {
                    if (advert.id === advertId) {
                        return {
                            ...advert,
                            isParticipating: true,
                            participantsCount: (advert.participantsCount || 0) + 1,
                            isSubscribed: false
                        };
                    }
                    return advert;
                })
            );
        } catch (err) {
            alert(err.message);
        }
    };

    const handleUnsubscribe = async (advertId) => {
        if (!isAuthenticated) { navigate('/login'); return; }
        try {
            await advertService.unsubscribeFromAdvert(advertId);
            setAdverts(prevAdverts =>
                prevAdverts.map(advert => {
                    if (advert.id === advertId) {
                        return {
                            ...advert,
                            isParticipating: false,
                            participantsCount: Math.max((advert.participantsCount || 0) - 1, 0)
                        };
                    }
                    return advert;
                })
            );
        } catch (err) {
            alert(err.message);
        }
    };

    const handleDelete = async (advertId) => {
        if (window.confirm(t('confirmDelete'))) {
            try {
                await advertService.deleteAdvert(advertId);
                await loadAdverts();
            } catch (err) {
                alert(err.message);
            }
        }
    };

    const handleEdit = (advertId) => navigate(`/add-advert?edit=${advertId}`);
    const handleApplyFilters = (newFilters) => applyFilters(newFilters);

    const getGameLevelDisplay = (level) => {
        return levelMap[level] || level || 'Не указан';
    };

    const tabs = [
        { id: 'all', label: t('allAdverts') },
        { id: 'my', label: t('myAdverts') },
        { id: 'participating', label: t('participating') }
    ];

    return (
        <div className={styles.homePage}>
            <div className={styles.hero}>
                <div className={styles.heroContent}>
                    <h1 className={styles.heroTitle}>{t('findTeam')}</h1>
                    <p className={styles.heroSubtitle}>{t('joinGames')}</p>
                    {isAuthenticated && !isAdminUser && (
                        <Button size="large" icon={FaPlus} onClick={() => navigate('/add-advert')}>{t('createAdvert')}</Button>
                    )}
                    {!isAuthenticated && (
                        <Button size="large" onClick={() => navigate('/login')}>{t('login')}</Button>
                    )}
                </div>
            </div>

            <div className={styles.tabsSection}>
                <div className={styles.container}>
                    <div className={styles.tabsHeader}>
                        <div className={styles.tabs}>
                            {tabs.map(tab => (
                                <button
                                    key={tab.id}
                                    className={`${styles.tab} ${activeTab === tab.id ? styles.activeTab : ''}`}
                                    onClick={() => setActiveTab(tab.id)}
                                >
                                    {tab.label}
                                </button>
                            ))}
                        </div>
                        <Button variant="outline" size="small" icon={FaFilter} onClick={() => setShowFilters(!showFilters)}>
                            {t('filters')}
                        </Button>
                    </div>

                    {showFilters && <FilterSection onApplyFilters={handleApplyFilters} initialFilters={filters} />}

                    {loading ? (
                        <div className={styles.loadingState}>
                            <div className={styles.spinner} />
                            <p>{t('loading')}</p>
                        </div>
                    ) : error ? (
                        <div className={styles.errorState}>
                            <p>{error}</p>
                            <Button onClick={loadAdverts}>{t('tryAgain')}</Button>
                        </div>
                    ) : adverts.length === 0 ? (
                        <div className={styles.emptyState}>
                            <p className={styles.emptyMessage}>{t('noAdverts')}</p>
                            {isAuthenticated && !isAdminUser && activeTab === 'all' && (
                                <Button onClick={() => navigate('/add-advert')}>{t('createFirst')}</Button>
                            )}
                        </div>
                    ) : (
                        <div className={styles.advertsGrid}>
                            {adverts.map((advert) => {
                                const isCreator = user && advert.userId === user.id;
                                const isParticipating = advert.isParticipating === true;
                                const isSubscribed = advert.isSubscribed === true;

                                return (
                                    <AdvertCard
                                        key={advert.id}
                                        advert={advert}
                                        isCreator={isCreator}
                                        isParticipating={isParticipating}
                                        isSubscribed={isSubscribed}
                                        isAdmin={isAdminUser}
                                        onSubscribe={() => handleSubscribe(advert.id)}
                                        onUnsubscribe={() => handleUnsubscribe(advert.id)}
                                        onSubscribeToWaiting={() => {}}
                                        onUnsubscribeFromWaiting={() => {}}
                                        onEdit={() => handleEdit(advert.id)}
                                        onDelete={() => handleDelete(advert.id)}
                                        onViewCreator={() => handleViewCreator(advert.userId)}
                                        onClick={() => navigate(`/advert/${advert.id}`)}
                                    />
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            {showCreatorModal && selectedCreator && (
                <div className={styles.modal} onClick={() => setShowCreatorModal(false)}>
                    <div className={styles.modalContent} onClick={(e) => e.stopPropagation()}>
                        <div className={styles.modalHeader}>
                            <h3>Информация о создателе</h3>
                            <button className={styles.closeBtn} onClick={() => setShowCreatorModal(false)}>×</button>
                        </div>
                        <div className={styles.creatorInfo}>
                            <p><strong>Имя:</strong> {selectedCreator.name}</p>
                            <p><strong>Email:</strong> {selectedCreator.email}</p>
                            <p><strong>Телефон:</strong> {selectedCreator.phone || 'Не указан'}</p>
                            <p><strong>Уровень игры:</strong> {getGameLevelDisplay(selectedCreator.gameLevel)}</p>
                            <p><strong>Статус:</strong> {selectedCreator.isBlocked ? 'Заблокирован' : 'Активен'}</p>
                        </div>
                        {isAdminUser && (
                            <>
                                <div className={styles.notificationSection}>
                                    <textarea
                                        className={styles.textarea}
                                        rows="3"
                                        placeholder="Введите текст уведомления..."
                                        value={notificationText}
                                        onChange={(e) => setNotificationText(e.target.value)}
                                    />
                                    <Button onClick={handleSendNotification}>Отправить уведомление</Button>
                                </div>
                                <div className={styles.modalActions}>
                                    <Button
                                        variant={selectedCreator.isBlocked ? 'success' : 'danger'}
                                        onClick={handleBlockUser}
                                    >
                                        {selectedCreator.isBlocked ? 'Разблокировать' : 'Заблокировать'}
                                    </Button>
                                </div>
                            </>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default HomePage;
